from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

from Team_Phoenix_Library import phoenix_gyro_spin_turn_the_old_way, phoenix_gyro_turn

# Set up.
left = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right = Motor(Port.F, Direction.CLOCKWISE)
drive_base2 = DriveBase(left, right, 62.4, 100)
left_atta = Motor(Port.C, Direction.COUNTERCLOCKWISE)
right_atta = Motor(Port.E, Direction.CLOCKWISE)

async def run_green_mission(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    await wait(0)
    await drive_base.straight(510)
    phoenix_gyro_spin_turn_the_old_way(100, -45, 40, -45, 'left', drive_base, left_drive, right_drive)
    await drive_base.straight(200)
    phoenix_gyro_spin_turn_the_old_way(100, 45, 30, 45, 'right', drive_base, left_drive, right_drive)
    phoenix_gyro_spin_turn_the_old_way(100, 42, 30, 42, 'right', drive_base, left_drive, right_drive)
    await multitask(
        left_attachment.run_angle(300, -40),
        right_attachment.run_angle(300, -45),
    )
    await drive_base.straight(135)
    drive_base.drive(200, 0)
    await wait(1000)
    drive_base.hold()

async def lift_arms(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    await wait(0)
    await multitask(
        left_attachment.run_angle(300, 40),
        right_attachment.run_angle(300, 45),
    )

async def lower_arms(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    await wait(0)
    await multitask(
        left_attachment.run_angle(300, -40),
        right_attachment.run_angle(300, -45),
    )

async def fungus_and_elder(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    await wait(0)
    await left_attachment.run_angle(500, -50)
    await left_attachment.run_angle(500, 50)

async def back_up(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    await wait(0)
    await drive_base.straight(-90)
    phoenix_gyro_spin_turn_the_old_way(100, 45, 30, 45, 'right', drive_base, left_drive, right_drive)
    await drive_base.straight(-320)
    phoenix_gyro_spin_turn_the_old_way(100, -45, 30, -45, 'left', drive_base, left_drive, right_drive)
    drive_base.drive(100, 0)
    await wait(2000)
    drive_base.hold()
    await drive_base.straight(-85)
    phoenix_gyro_spin_turn_the_old_way(100, 90, 30, 90, 'right', drive_base, left_drive, right_drive)
    drive_base.drive(250, 0)
    await wait(3000)

async def main():
    await lift_arms(drive_base2, left, right, left_atta, right_atta)
    await run_green_mission(drive_base2, left, right, left_atta, right_atta)
    await lift_arms(drive_base2, left, right, left_atta, right_atta)
